56: /** Detect against a vocabulary containing these creature types / keywords. */
57: function signalsFor(
58:   row: CardRow,
59:   creatureTypes: string[] = [],
60:   keywords: string[] = [],
61: ): SignalMatch[] {
62:   const vocab = buildVocabulary(creatureTypes, keywords);
63:   return detectSignals(buildCardFacts(row, vocab), vocab);
64: }
65: 
66: function find(
67:   signals: SignalMatch[],
68:   archetype: string,
69:   qualifier?: string,
70: ): SignalMatch | undefined {
71:   return signals.find((s) => s.archetype === archetype && s.qualifier === qualifier);
72: }
73: 
74: function rolesOf(signals: SignalMatch[], archetype: string, qualifier?: string): Role[] {
75:   return (find(signals, archetype, qualifier)?.roles ?? []).slice().sort();
76: }
