772: type Matcher = RegExp | ((f: CardFacts, vocab: Vocabulary) => boolean);
773: 
774: export interface ArchetypeDef {
775:   key: string;
776:   label: string;
777:   description: string;
778:   weight: number;
779:   /** Per-role matchers. A card matching any matcher for a role gains it. */
780:   roles: Partial<Record<Role, Matcher[]>>;
781:   /**
782:    * When set, a match may be narrowed to a creature type the card's text
783:    * restricts it to — the Sliver Gravemother case. A qualified signal only
784:    * counts supporters of that type, and separately implies kindred for it.
785:    */
786:   qualifiable?: QualifierKind;
787:   /**
788:    * Which role is this archetype's identity, and how many citable cards must
789:    * show it for the archetype to be reported at all. Defaults to `rewards`
790:    * x1 — see `definingRequirement`. Membership (any role) still counts
791:    * *cards*, once this bar is cleared; it just cannot clear the bar alone.
792:    */
793:   definingRole?: Role;
794:   definingMinimum?: number;
795: }
796: 
797: function matches(matcher: Matcher, facts: CardFacts, vocab: Vocabulary): boolean {
798:   return typeof matcher === 'function' ? matcher(facts, vocab) : matcher.test(facts.text);
799: }
