1113: // ---------------------------------------------------------------------------
1114: // Detection
1115: // ---------------------------------------------------------------------------
1116: 
1117: /** Splits text into clauses, so a qualifier is only picked up from the same
1118:  * sentence as the payoff it restricts. */
1119: function clauses(text: string): string[] {
1120:   return text.split(/[.;\n]/).filter((c) => c.trim().length > 0);
1121: }
1122: 
1123: /**
1124:  * The creature type a qualifiable archetype's payoff is restricted to, if any.
1125:  *
1126:  * Only a type mentioned in the same clause as the payoff counts — a commander
1127:  * that reanimates anything and separately happens to mention Goblins is not a
1128:  * Goblin-restricted reanimator.
1129:  */
1130: function findQualifier(facts: CardFacts, def: ArchetypeDef, vocab: Vocabulary): string | undefined {
1131:   // Counters' qualifying evidence usually lives in the PRODUCES clause
1132:   // itself ("enters with three +1/+1 counters" has no separate payoff
1133:   // clause to restrict from), not just rewards/consumes — so every clause
1134:   // is a candidate, and findCounterKind is precise enough on its own not to
1135:   // need pre-filtering by which role matched.
1136:   if (def.qualifiable === 'counterType') {
1137:     for (const clause of clauses(facts.text)) {
1138:       const kind = findCounterKind(clause);
1139:       if (kind) return kind;
1140:     }
1141:     return undefined;
1142:   }
1143: 
1144:   const payoffMatchers = [...(def.roles.rewards ?? []), ...(def.roles.consumes ?? [])];
1145:   for (const clause of clauses(facts.text)) {
1146:     const hit = payoffMatchers.some((m) => (typeof m === 'function' ? false : m.test(clause)));
1147:     if (!hit) continue;
1148:     for (const word of wordsIn(clause)) {
1149:       const type = vocab.typeByWord.get(word);
1150:       if (type) return type;
1151:     }
1152:   }
1153:   return undefined;
1154: }
1155: 
