24: let counter = 0;
25: function makeCard(overrides: Partial<CardRow> = {}): CardRow {
26:   const name = overrides.name ?? `Test Card ${counter++}`;
27:   return {
28:     oracle_id: name,
29:     name,
30:     name_lower: name.toLowerCase(),
31:     mana_cost: null,
32:     cmc: 0,
33:     type_line: 'Creature — Human',
34:     oracle_text: '',
35:     colors: '[]',
36:     color_identity: '[]',
37:     keywords: '[]',
38:     creature_types: '[]',
39:     power: '1',
40:     toughness: '1',
41:     scryfall_uri: null,
42:     partner_ability: null,
43:     partner_target: null,
44:     is_background: 0,
45:     legality_commander: 'legal',
46:     game_changer: 0,
47:     is_legendary: 0,
48:     is_commander_eligible: 0,
49:     image_uri: null,
50:     back_image_uri: null,
51:     back_name: null,
52:     ...overrides,
53:   };
54: }
55: 
56: /** Detect against a vocabulary containing these creature types / keywords. */
57: function signalsFor(
58:   row: CardRow,
59:   creatureTypes: string[] = [],
60:   keywords: string[] = [],
61: ): SignalMatch[] {
62:   const vocab = buildVocabulary(creatureTypes, keywords);
63:   return detectSignals(buildCardFacts(row, vocab), vocab);
64: }
65: 
66: function find(
67:   signals: SignalMatch[],
68:   archetype: string,
69:   qualifier?: string,
70: ): SignalMatch | undefined {
71:   return signals.find((s) => s.archetype === archetype && s.qualifier === qualifier);
72: }
73: 
74: function rolesOf(signals: SignalMatch[], archetype: string, qualifier?: string): Role[] {
75:   return (find(signals, archetype, qualifier)?.roles ?? []).slice().sort();
76: }
