1160:     if (matchers?.some((m) => matches(m, facts, vocab))) found.push(role);
1161:   }
1162:   return found;
1163: }
1164: 
1165: /**
1166:  * The creature types a card could possibly relate to.
1167:  *
1168:  * Derived from the card outward rather than by testing every type in the
1169:  * game against it. That is not just an optimisation: looping the full
1170:  * vocabulary meant 647 types x 884 keywords of regex per card, which took
1171:  * 82 seconds across the card pool and made precomputing signals impractical.
1172:  * Scanning the card's own words and intersecting with the known-type set is
1173:  * proportional to the card, not to Magic's type list.
1174:  */
1175: function candidateTypes(facts: CardFacts, vocab: Vocabulary): string[] {
1176:   const found = new Set<string>();
1177:   // Structured, and free.
1178:   for (const type of facts.creatureTypes) found.add(type);
1179:   for (const type of facts.producedTokenTypes) found.add(type);
1180:   // Textual: every word the card uses, looked up rather than searched for.
1181:   for (const word of wordsIn(facts.text)) {
1182:     const type = vocab.typeByWord.get(word);
1183:     if (type) found.add(type);
1184:   }
1185:   return [...found];
1186: }
1187: 
1188: /** Kindred, one signal per creature type. Membership is structural (the card's
1189:  * own type, or a token type it makes); caring about the type is textual. */
1190: function detectKindred(facts: CardFacts, vocab: Vocabulary): SignalMatch[] {
1191:   const out: SignalMatch[] = [];
1192:   for (const type of candidateTypes(facts, vocab)) {
1193:     const roles: Role[] = [];
1194:     // Structured data only — never the name. Goblin Sharpshooter is a Goblin
1195:     // because its type line says so.
1196:     if (facts.creatureTypes.includes(type)) roles.push('is');
1197:     // "Create two 1/1 red Goblin creature tokens" makes Krenko's Command a
1198:     // Goblin card even though a Sorcery has no creature type.
1199:     if (facts.producedTokenTypes.includes(type)) roles.push('produces');
1200: 
1201:     // Naming the token's type is not caring about the type — "create two 1/1
1202:     // red Goblin creature tokens" already counted as `produces` above, and
1203:     // must not also read as a payoff. Krenko's Command says "Goblin" exactly
1204:     // once, in the token's name, and is a producer only; Krenko, Mob Boss
1205:     // says it twice — once naming the token, once counting "the number of
1206:     // Goblins you control" — and that second mention is the payoff.
1207:     const caringText = withoutTokenDescriptors(facts.text, type);
1208: 
1209:     for (const clause of clauses(caringText)) {
1210:       if (!wordPattern(type).test(clause)) continue;
1211:       // Sacrifice reads the COST side only — Sophia's "Sacrifice an
1212:       // artifact token: Put a +1/+1 counter on each Dog you control" must
1213:       // not register as consuming Dogs merely because "Dog" appears in the
1214:       // effect. Tap/discard/exile aren't restricted the same way; nothing
1215:       // in the corpus needed it and widening them isn't this fix's job.
1216:       const consumesType = sacrificesKind(clause, type) || /\btap\b|\bdiscard\b|\bexile\b/i.test(clause);
1217:       if (consumesType) {
1218:         roles.push('consumes');
1219:         // An activated ability is "cost: effect", so a clause that spends the
1220:         // type also hands something back. Lathril's "Tap ten untapped Elves
1221:         // you control: Each opponent loses 10 life" consumes Elves *and*
1222:         // rewards you for having had them.
1223:         if (clause.includes(':')) roles.push('rewards');
1224:       }
1225:       if (
1226:         /\bget\b|\bgains?\b|\bhas\b|\bhave\b|whenever|for each|number of|search|\blose\b|\bloses\b/i.test(
1227:           clause,
1228:         )
1229:       ) {
1230:         roles.push('rewards');
1231:       }
1232:       // Archetype-scoped, not generic hexproof: this clause already had to
1233:       // name the type to reach this point (the `wordPattern(type)` guard
1234:       // above), so "Sliver creatures you control have indestructible" earns
1235:       // `protects` for kindred:Sliver specifically — a card that just grants
1236:       // hexproof to "target creature" never reaches this branch at all.
1237:       if (/\b(?:indestructible|hexproof|protection from|shroud|ward)\b/i.test(clause)) {
1238:         roles.push('protects');
1239:       }
1240:     }
1241: 
1242:     if (roles.length === 0) continue;
1243:     out.push({
1244:       archetype: 'kindred',
1245:       label: `${type} Kindred`,
1246:       description: `${pluralOfType(type)}, and cards that care about having them.`,
1247:       weight: 15,
1248:       qualifier: type,
1249:       qualifierKind: 'creatureType',
1250:       roles: [...new Set(roles)],
1251:     });
1252:   }
1253:   return out;
1254: }
1255: 
1256: /**
1257:  * Keyword care, one signal per keyword.
1258:  *
1259:  * A keyword on its own is not a synergy — Trample is a good thing to have,
1260:  * not a deck. What matters is a commander that *cares* about the keyword
1261:  * (grants it, or triggers off it), which is the same active-role test kindred
1262:  * uses. Having the keyword is `is` and never qualifies a commander on its own.
1263:  */
1264: function detectKeywordCare(facts: CardFacts, vocab: Vocabulary): SignalMatch[] {
1265:   const out: SignalMatch[] = [];
1266:   for (const keyword of candidateKeywords(facts, vocab)) {
1267:     if (EXCLUDED_KEYWORDS.has(keyword.toLowerCase())) continue;
1268:     const roles: Role[] = [];
1269:     if (facts.keywords.includes(keyword)) roles.push('is');
1270:     // Reuses detectKindred's own word-or-plural matcher — "Foods", "Clues"
1271:     // and "Treasures" never matched a bare, unpluralised keyword before.
1272:     const pattern = wordPattern(keyword);
1273:     for (const clause of clauses(facts.text)) {
1274:       if (!pattern.test(clause)) continue;
1275:       // "Creatures you control gain trample" / "have flying" — granting it to
1276:       // others, which is the Craterhoof shape.
1277:       if (/\b(?:gains?|have|has|gets?)\b/i.test(clause)) roles.push('produces');
1278:       if (/whenever|for each|number of/i.test(clause)) roles.push('rewards');
1279:     }
1280:     if (roles.length === 0) continue;
1281:     out.push({
1282:       archetype: 'keywordCare',
1283:       label: keyword,
1284:       description: `Cards with ${keyword}, where the commander actually cares about it.`,
1285:       weight: 8,
1286:       qualifier: keyword,
1287:       qualifierKind: 'keyword',
1288:       roles: [...new Set(roles)],
1289:     });
1290:   }
1291:   return out;
1292: }
1293: 
1294: /**
1295:  * Keywords that are structural rather than thematic.
1296:  *
1297:  * The Partner family says who can be your commander, not what your deck
1298:  * wants to do. Surfacing "Partner" as a shared keyword would be a confusing
1299:  * echo of the dedicated partner/background handling rather than a second,
1300:  * unrelated signal.
1301:  */
1302: const EXCLUDED_KEYWORDS = new Set([
1303:   'partner',
1304:   'partner with',
1305:   'friends forever',
1306:   'choose a background',
1307:   "doctor's companion",
1308: ]);
1309: 
1310: /** The keywords a card could possibly relate to. Same inversion as
1311:  * `candidateTypes` — look up the card's own words instead of testing all 884
1312:  * keywords against it. Multi-word keywords ("first strike") can't be found by
1313:  * single-word lookup, so those few are still tested directly. */
1314: function candidateKeywords(facts: CardFacts, vocab: Vocabulary): string[] {
1315:   const found = new Set<string>();
1316:   for (const keyword of facts.keywords) found.add(keyword);
1317:   for (const word of wordsIn(facts.text)) {
1318:     const keyword = vocab.keywordByWord.get(word);
1319:     if (keyword) found.add(keyword);
1320:   }
1321:   const lowerText = facts.text.toLowerCase();
1322:   for (const keyword of vocab.multiWordKeywords) {
1323:     if (lowerText.includes(keyword.toLowerCase())) found.add(keyword);
1324:   }
1325:   return [...found];
1326: }
1327: 
1328: /**
1329:  * Which role is an archetype's identity, and how many citable cards must
1330:  * show it before the archetype is reported at all.
1331:  *
1332:  * Membership (any role) still counts cards once this bar is cleared — a
1333:  * theme's card count is not limited to the defining-role cards — but
1334:  * membership alone cannot clear it. `kindred` is generated per creature type
1335:  * rather than listed in `ARCHETYPES`, so it is special-cased here rather than
1336:  * carrying its own `ArchetypeDef`. `keywordCare` is likewise absent from
1337:  * `ARCHETYPES` and so falls through to the default (`rewards` x1) — granting
1338:  * a keyword is `produces`, not `rewards`, so this is what stops a commander
1339:  * that merely hands out Flying from reading as a Flying deck.
1340:  */
1341: export function definingRequirement(archetype: string): { role: Role; minimum: number } {
1342:   if (archetype === 'kindred') {
1343:     // "Ten Wizards plus one incidental pump is not a Wizard deck" — see
1344:     // archetypes.md. Membership is structural and free to claim, so kindred
1345:     // needs more than one card that actually cares.
1346:     return { role: 'rewards', minimum: 2 };
1347:   }
1348:   const def = ARCHETYPES.find((a) => a.key === archetype);
1349:   return { role: def?.definingRole ?? 'rewards', minimum: def?.definingMinimum ?? 1 };
1350: }
1351: 
1352: /** Every archetype this card participates in, and how. */
1353: export function detectSignals(facts: CardFacts, vocab: Vocabulary): SignalMatch[] {
1354:   const out: SignalMatch[] = [];
1355: 
1356:   for (const def of ARCHETYPES) {
1357:     const roles = rolesFor(def, facts, vocab);
1358:     if (roles.length === 0) continue;
1359:     const qualifier = def.qualifiable ? findQualifier(facts, def, vocab) : undefined;
1360:     out.push({
1361:       archetype: def.key,
1362:       label: qualifier ? `${def.label} (${qualifier})` : def.label,
1363:       description: def.description,
1364:       weight: def.weight,
1365:       qualifier,
1366:       qualifierKind: qualifier ? def.qualifiable : undefined,
1367:       roles,
1368:     });
1369:   }
1370: 
1371:   out.push(...detectKindred(facts, vocab));
1372:   out.push(...detectKeywordCare(facts, vocab));
1373:   return out;
1374: }
1375: 
1376: /**
1377:  * Presentation details for a signal read back out of storage.
1378:  *
1379:  * The `card_signals` table records what a card *is* — archetype, qualifier,
1380:  * roles — and deliberately not how to label it. Labels and weights are
1381:  * presentation, and storing them would mean a reworded description needed a
1382:  * full re-import to take effect. This rebuilds them from the catalog instead.
1383:  */
1384: export function archetypeDisplay(
1385:   archetype: string,
1386:   qualifier: string | null,
1387: ): { label: string; description: string; weight: number } {
1388:   if (archetype === 'kindred' && qualifier) {
1389:     return {
1390:       label: `${qualifier} Kindred`,
1391:       description: `${pluralOfType(qualifier)}, and cards that care about having them.`,
1392:       weight: 15,
1393:     };
1394:   }
1395:   if (archetype === 'keywordCare' && qualifier) {
1396:     return {
1397:       label: qualifier,
1398:       description: `Cards with ${qualifier}, where the commander actually cares about it.`,
1399:       weight: 8,
1400:     };
1401:   }
1402: 
1403:   const def = ARCHETYPES.find((a) => a.key === archetype);
1404:   if (!def) {
1405:     // An archetype in the database that the catalog no longer defines — the
1406:     // shape of things after a rename without a re-import. Degrade to the raw
1407:     // key rather than crashing; the next import drops the row.
1408:     return { label: archetype, description: '', weight: 10 };
1409:   }
1410:   return {
1411:     label: qualifier ? `${def.label} (${qualifier})` : def.label,
1412:     description: def.description,
1413:     weight: def.weight,
1414:   };
1415: }

