input.oldString:
const payoffMatchers = [...(def.roles.rewards ?? []), ...(def.roles.consumes ?? [])];
for (const clause of clauses(facts.text)) {
  const matcher = payoffMatchers.find(
    (m) => typeof m === 'regexp' && m.test(clause),
  );
  if (!matcher) continue;
  const match = clause.match(matcher);
  if (!match) continue;
  // The creature type that the payoff restricts to appears in the matched
  // portion of the regex, not the entire clause.  For "exile all Zombies,
  // then return all Human creature cards from your graveyard to the
  // battlefield" the clause contains both creature types, but only the part
  // matched by the "return" regex matters.
  for (const word of wordsIn(match[0])) {
    const type = vocab.typeByWord.get(word);
    if (type) return type;
  }
}

input.newString:
const payoffMatchers = [...(def.roles.rewards ?? []), ...(def.roles.consumes ?? [])];
for (const clause of clauses(facts.text)) {
  const matcher = payoffMatchers.find(
    (m) => typeof m === 'regexp' && m.test(clause),
  );
  if (!matcher) continue;
  const match = clause.match(matcher);
  if (!match) continue;
  // For long matches (e.g. "return all Human creature cards from your
  // graveyard to the battlefield") the creature type lives in the matched
  // portion, so scanning only the match avoids picking up creature types
  // from unrelated actions in the same clause ("exile all Zombies").
  // For short / keyword-only matches (e.g. /\bencore\b/) the match is
  // just the keyword itself, so we fall back to the full clause.
  const searchText = match[0].length > 15 ? match[0] : clause;
  for (const word of wordsIn(searchText)) {
    const type = vocab.typeByWord.get(word);
    if (type) return type;
  }
}

