const payoffMatchers = [...(def.roles.rewards ?? []), ...(def.roles.consumes ?? [])];
for (const clause of clauses(facts.text)) {
  const hit = payoffMatchers.some((m) => (typeof m === 'function' ? false : m.test(clause)));
  if (!hit) continue;
  for (const word of wordsIn(clause)) {
    const type = vocab.typeByWord.get(word);
    if (type) return type;
  }
}
return undefined;

input.newString:
const payoffMatchers = [...(def.roles.rewards ?? []), ...(def.roles.consumes ?? [])];
for (const clause of clauses(facts.text)) {
  // Find the specific matching regex and its match text.
  let matchedText = '';
  for (const m of payoffMatchers) {
    if (typeof m !== 'regexp') continue;
    const match = m.exec(clause);
    if (match) {
      matchedText = match[0];
      break;
    }
  }
  if (!matchedText) continue;

  // For long matches (>15 chars) the creature type is likely in the
  // matched portion (e.g. "return all Human creature cards from your
  // graveyard"). For short/keyword-only matches like /\bencore\b/i,
  // fall back to the full clause.
  const searchText = matchedText.length > 15 ? matchedText : clause;

  for (const word of wordsIn(searchText)) {
    const type = vocab.typeByWord.get(word);
    if (type) return type;
  }
}
return undefined;

